/* ---- the hidden treasure: the frogs' tune ---- */
/* Whoever touches the reeds by the canal at dusk sets the frogs off, and they croak the chapter's tune: heard, and seen (the reeds stir and
   rings spread on the water), since a phone may be muted. It changes nothing. */
function croak24(){G.frogs24=performance.now();const c=AU.ctx;if(c&&c.state==='running'){const t0=c.currentTime+.05,dt=MUSIC.dt;
    for(const[s,d,l]of FROGS24){const f=mtof(note(d,-12)),t=t0+s*dt;tone({t,d:Math.min(.5,l*dt*.7),v:.09,f,to:f*.9,type:'sawtooth'});noise({t,d:.06,v:.03,f:400,type:'bandpass',q:3})}}
  treasure()}
